"""
Bulletproof HTML for every email the app sends -- table-based layout,
inline styles, solid bgcolor fallback behind every gradient (Outlook
desktop's Word rendering engine ignores CSS background-image on table
cells and falls back to bgcolor), Arial as the primary font (the one face
with guaranteed Hebrew glyph coverage on Windows/macOS/iOS/Android alike --
Segoe UI, used elsewhere in the app, is Windows-only), and an explicit
"light only" color-scheme declaration so Gmail/Outlook dark-mode heuristics
don't remap the brand colors. Approved as a mockup (an Artifact) before
being wired into mailer.py's real send_email() calls in otp.py/app.py.
"""

from __future__ import annotations

FONT = "Arial, \'Segoe UI\', Tahoma, sans-serif"
MONO = "\'Courier New\', Courier, monospace"

# The office's circular gold emblem, cropped square (240x240) -- the exact
# same asset already embedded in wizard.html's own header chip, reused here
# so the emblem in every email matches the one in the live form pixel-for-
# pixel rather than being a second, possibly-inconsistent crop.
_EMBLEM = "data:image/png;base64,"


def _brand_header() -> str:
    return f'''<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;">
  <tr>
    <td bgcolor="#4a0a6b" style="background-color:#4a0a6b; background-image:linear-gradient(135deg,#7B2D8B 0%,#4a0a6b 60%,#1a0030 100%); padding:20px 26px;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" dir="rtl" align="right"><tr>
        <td width="38" valign="middle">
          <table role="presentation" cellpadding="0" cellspacing="0" border="0" bgcolor="#ffffff" style="background-color:#ffffff; border-radius:50%; width:38px; height:38px;">
            <tr><td align="center" valign="middle" style="padding:5px;">
              <img src="{_EMBLEM}" width="28" height="28" alt="לוגו אורן דולב רואה חשבון" style="display:block; border:0; width:28px; height:28px;">
            </td></tr>
          </table>
        </td>
        <td style="padding-right:12px;" valign="middle" align="right">
          <div style="font-family:{FONT}; color:#ffffff; font-size:15px; font-weight:bold; line-height:1.3;">דוח תיאום נסיעה לחו"ל</div>
          <div style="font-family:{FONT}; color:#e3c7ef; font-size:12px; margin-top:2px;">אורן דולב, רואה חשבון &middot; odcpa.co.il</div>
        </td>
      </tr></table>
    </td>
  </tr>
</table>'''


def _footer() -> str:
    return f'''<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
  <tr><td bgcolor="#ffffff" style="background-color:#ffffff; border-top:1px solid #e0d0f0; padding:16px 26px;" align="center">
    <span style="font-family:{FONT}; font-size:11px; color:#7a6a8a;">מייל אוטומטי &middot; odcpa.co.il</span>
  </td></tr>
</table>'''


def _wrap(body_inner: str) -> str:
    return f'''<!doctype html>
<html dir="rtl" lang="he">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
</head>
<body style="margin:0; padding:0; background-color:#f4f0f8;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f4f0f8" style="background-color:#f4f0f8;">
  <tr><td align="center" style="padding:24px 12px;">
    <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px; max-width:600px;" dir="rtl">
      <tr><td bgcolor="#ffffff" style="background-color:#ffffff; border-radius:14px; overflow:hidden;">
        {_brand_header()}
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
          <td style="padding:28px 26px 30px;" align="right">
            {body_inner}
          </td>
        </tr></table>
        {_footer()}
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>'''


def otp_email_html(code: str) -> str:
    body = f'''<div style="font-family:{FONT}; font-size:15px; font-weight:bold; color:#1a0030; margin:0 0 12px;">שלום,</div>
<div style="font-family:{FONT}; font-size:14.5px; color:#1a0030; line-height:1.6; margin:0 0 20px;">קיבלנו בקשה לאמת את כתובת המייל שלך לצורך מילוי טופס דיווח נסיעה. הקוד שלך:</div>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:0 auto;"><tr>
  <td bgcolor="#f4f0f8" style="background-color:#f4f0f8; border:1px solid #e0d0f0; border-radius:10px; padding:16px 28px;" align="center">
    <span style="font-family:{MONO}; font-size:30px; font-weight:bold; letter-spacing:10px; color:#4a0a6b;" dir="ltr">{code}</span>
  </td>
</tr></table>
<div style="font-family:{FONT}; font-size:12px; color:#7a6a8a; text-align:center; margin:12px 0 0;">בתוקף ל-10 דקות &middot; אם לא ביקשת קוד זה, אפשר להתעלם מהמייל</div>'''
    return _wrap(body)


def draft_link_email_html(link: str) -> str:
    body = f'''<div style="font-family:{FONT}; font-size:15px; font-weight:bold; color:#1a0030; margin:0 0 12px;">שלום,</div>
<div style="font-family:{FONT}; font-size:14.5px; color:#1a0030; line-height:1.6; margin:0 0 20px;">שמרנו את הטיוטה שלך של טופס הנסיעה. אפשר לחזור אליה ולהמשיך למלא בכל שלב &mdash; כל מה שכבר הזנת יישאר כמו שהוא.</div>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:0 auto 20px;"><tr>
  <td bgcolor="#5c1f6b" style="background-color:#5c1f6b; background-image:linear-gradient(135deg,#7B2D8B,#4a0a6b); border-radius:8px;">
    <a href="{link}" style="display:inline-block; padding:13px 30px; font-family:{FONT}; font-size:14px; font-weight:bold; color:#ffffff; text-decoration:none;">להמשך מילוי הטופס &larr;</a>
  </td>
</tr></table>
<div style="font-family:{FONT}; font-size:13px; color:#7a6a8a; margin:0 0 8px;">אם הכפתור לא עובד, אפשר להעתיק את הקישור:</div>
<div style="font-family:{MONO}; font-size:11.5px; color:#7a6a8a; background-color:#f4f0f8; border-radius:8px; padding:10px 12px; word-break:break-all;" dir="ltr">{link}</div>
<div style="font-family:{FONT}; font-size:12px; color:#7a6a8a; margin:14px 0 0;">הקישור אישי, חד-פעמי, ובתוקף ל-7 ימים.</div>'''
    return _wrap(body)


def report_copy_email_html(
    contact_name: str, trip_id: str, amount_ils: float,
    destination: str, country: str, start_date: str, end_date: str,
    traveler_count: int, pdf_filename: str, pdf_size_kb: int,
) -> str:
    body = f'''<div style="font-family:{FONT}; font-size:15px; font-weight:bold; color:#1a0030; margin:0 0 12px;">שלום {contact_name},</div>
<div style="font-family:{FONT}; font-size:14.5px; color:#1a0030; line-height:1.6; margin:0 0 18px;">הדוח עבור נסיעתך הופק בהצלחה ומצורף כאן כ-PDF. עותק זה נשמר גם אצלנו במשרד.</div>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#4a0a6b" style="background-color:#4a0a6b; background-image:linear-gradient(135deg,#7B2D8B,#4a0a6b); border-radius:10px; margin:0 0 16px;"><tr>
  <td style="padding:18px 22px;" align="right" valign="middle">
    <div style="font-family:{FONT}; color:#e3c7ef; font-size:11px; font-weight:bold; letter-spacing:.03em;">סכום מוכר לצרכי מס</div>
    <div style="font-family:{FONT}; color:#ffffff; font-size:26px; font-weight:800;">&#8362; {amount_ils:,.2f}</div>
  </td>
  <td style="padding:18px 22px;" align="left" valign="middle">
    <span style="font-family:{MONO}; color:#e3c7ef; font-size:11px;" dir="ltr">{trip_id}</span>
  </td>
</tr></table>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f4f0f8" style="background-color:#f4f0f8; border:1px solid #e0d0f0; border-radius:9px; margin:0 0 16px;"><tr>
  <td width="30" style="padding:10px 0 10px 14px;" align="center" valign="middle">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" bgcolor="#7B2D8B" style="background-color:#7B2D8B; border-radius:7px; width:30px; height:30px;"><tr>
      <td align="center" valign="middle" style="font-family:{FONT}; color:#ffffff; font-size:10px; font-weight:bold;">PDF</td>
    </tr></table>
  </td>
  <td style="padding:10px 14px 10px 0;" align="right" valign="middle">
    <div style="font-family:{FONT}; font-size:13px; font-weight:bold; color:#1a0030;">{pdf_filename}</div>
  </td>
  <td style="padding:10px 14px 10px 0;" align="left" valign="middle">
    <span style="font-family:{FONT}; font-size:11px; color:#7a6a8a;" dir="ltr">{pdf_size_kb} KB</span>
  </td>
</tr></table>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="font-family:{FONT}; font-size:13px;">
  <tr><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#7a6a8a;" align="right">יעד</td><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#1a0030; font-weight:600;" align="left" dir="ltr">{destination}, {country}</td></tr>
  <tr><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#7a6a8a;" align="right">תאריכים</td><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#1a0030; font-weight:600;" align="left" dir="ltr">{start_date} &ndash; {end_date}</td></tr>
  <tr><td style="padding:8px 0; color:#7a6a8a;" align="right">נוסעים</td><td style="padding:8px 0; color:#1a0030; font-weight:600;" align="left">{traveler_count}</td></tr>
</table>

<div style="font-family:{FONT}; font-size:13px; color:#7a6a8a; margin:18px 0 0;">שאלות על הדוח? פשוט להשיב למייל הזה.</div>
<div style="font-family:{FONT}; font-size:13px; color:#7a6a8a; margin:20px 0 0;">בברכה,<br><b style="color:#1a0030;">אורן דולב, רואה חשבון</b></div>'''
    return _wrap(body)


def new_submission_email_html(
    contact_name: str, contact_email: str, trip_id: str, amount_ils: float,
    destination: str, country: str, pdf_filename: str, pdf_size_kb: int,
) -> str:
    body = f'''<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 14px;"><tr>
  <td bgcolor="#fdf3e0" style="background-color:#fdf3e0; border-radius:100px; padding:4px 12px;">
    <span style="font-family:{FONT}; font-size:11px; font-weight:bold; color:#b8860b;">הגשה חדשה</span>
  </td>
</tr></table>
<div style="font-family:{FONT}; font-size:14.5px; color:#1a0030; line-height:1.6; margin:0 0 16px;">התקבלה הגשה חדשה מ-<b dir="ltr" style="unicode-bidi:embed;">{contact_email}</b>.</div>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="font-family:{FONT}; font-size:13px; margin:0 0 16px;">
  <tr><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#7a6a8a;" align="right">לקוח</td><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#1a0030; font-weight:600;" align="left">{contact_name}</td></tr>
  <tr><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#7a6a8a;" align="right">יעד</td><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#1a0030; font-weight:600;" align="left" dir="ltr">{destination}, {country}</td></tr>
  <tr><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#7a6a8a;" align="right">סכום מוכר</td><td style="padding:8px 0; border-bottom:1px solid #e0d0f0; color:#1a0030; font-weight:600;" align="left">&#8362; {amount_ils:,.2f}</td></tr>
  <tr><td style="padding:8px 0; color:#7a6a8a;" align="right">מספר אסמכתא</td><td style="padding:8px 0; color:#1a0030; font-weight:600;" align="left" dir="ltr">{trip_id}</td></tr>
</table>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f4f0f8" style="background-color:#f4f0f8; border:1px solid #e0d0f0; border-radius:9px; margin:0 0 16px;"><tr>
  <td width="30" style="padding:10px 0 10px 14px;" align="center" valign="middle">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" bgcolor="#7B2D8B" style="background-color:#7B2D8B; border-radius:7px; width:30px; height:30px;"><tr>
      <td align="center" valign="middle" style="font-family:{FONT}; color:#ffffff; font-size:10px; font-weight:bold;">PDF</td>
    </tr></table>
  </td>
  <td style="padding:10px 14px 10px 0;" align="right" valign="middle">
    <div style="font-family:{FONT}; font-size:13px; font-weight:bold; color:#1a0030;">{pdf_filename}</div>
  </td>
  <td style="padding:10px 14px 10px 0;" align="left" valign="middle">
    <span style="font-family:{FONT}; font-size:11px; color:#7a6a8a;" dir="ltr">{pdf_size_kb} KB</span>
  </td>
</tr></table>

<div style="font-family:{FONT}; font-size:12.5px; color:#7a6a8a;">אפשר גם לצפות בהגשה ישירות בפאנל הניהול.</div>'''
    return _wrap(body)
